// WF-99 · Clasificación del fallo.
//
// No todos los errores merecen la misma respuesta, y tratarlos igual produce
// el peor resultado posible: o se despierta a la guardia por un 429 que se
// resolvió solo, o se entierra un 401 de credencial caducada entre el ruido
// hasta que alguien nota que el SOAR lleva dos días ciego.
//
//   TRANSITORIO  → se registra, no se avisa. El reintento del nodo ya actuó.
//   CONFIGURACIÓN→ aviso inmediato. No se arregla solo y deja el SOAR ciego.
//   DATOS        → aviso al equipo de detección: una regla de origen está mal.
//   DESCONOCIDO  → aviso, por si acaso.

const e = $input.first().json;

const mensaje = e.execution?.error?.message ?? e.error?.message ?? 'sin mensaje';
const nodo = e.execution?.lastNodeExecuted ?? 'desconocido';
const flujo = e.workflow?.name ?? 'desconocido';
const ejecucionId = e.execution?.id ?? null;

function clasificar(msg) {
  const m = String(msg).toLowerCase();

  // Fallos de credencial o permisos: no se arreglan solos.
  if (/401|403|unauthorized|forbidden|invalid.*(api key|token|credential)/.test(m)) {
    return { tipo: 'configuracion', severidad: 'critica', avisar: true };
  }
  // Cuotas y cortes de red: el reintero del nodo ya lo intentó.
  if (/429|rate.?limit|etimedout|econnreset|econnrefused|socket hang up|503|502|504/.test(m)) {
    return { tipo: 'transitorio', severidad: 'baja', avisar: false };
  }
  // Payload que no encaja: la regla de detección de origen está mal montada.
  if (/normalización fallida|json|parse|unexpected token|no se pudo parsear/.test(m)) {
    return { tipo: 'datos', severidad: 'media', avisar: true };
  }
  return { tipo: 'desconocido', severidad: 'media', avisar: true };
}

const clase = clasificar(mensaje);

return [
  {
    json: {
      flujo,
      nodo,
      mensaje: String(mensaje).slice(0, 500),
      ejecucionId,
      ...clase,
      // Enlace directo a la ejecución fallida: sin esto, depurar exige buscar
      // a mano entre miles de ejecuciones.
      urlDepuracion: ejecucionId ? `${$env.N8N_EDITOR_BASE_URL ?? ''}execution/${ejecucionId}` : null,
      timestamp: new Date().toISOString(),
    },
  },
];

// WF-99 · Registro silencioso de fallos transitorios.
//
// No se avisa, pero SÍ se cuenta. Un solo 429 de VirusTotal es rutina; cien
// en una hora significa que la caché de IoC no está funcionando o que el
// volumen superó lo que el free tier soporta — y eso es una decisión de
// arquitectura, no una incidencia puntual.

const e = $input.first().json;

return [
  {
    json: {
      evento: 'error_transitorio',
      flujo: e.flujo,
      nodo: e.nodo,
      tipo: e.tipo,
      mensaje: e.mensaje,
      timestamp: e.timestamp,
    },
  },
];
